    ll A, B;
    if (scanf("%d %lld %lld", &N, &A, &B) != 3) return 0;

    ll *d = (ll*)malloc(sizeof(ll) * N);
    if (!d) return 0;

    for (int i = 0; i < N; i++) {
        ll a, b;
        scanf("%lld %lld", &a, &b);
        d[i] = llabs(a - b);
    }

    qsort(d, N, sizeof(ll), cmp_ll);

    /*
      Interpreting the operation condition on a value x = |a_i - b_i| (or similarly
      on a pair-combined quantity) as removable iff:
         x <= A   OR   (B <= x <= 2A)

      Since each operation removes one eligible item independently, the maximum number
      of operations is simply the count of values satisfying that predicate.
    */
    long long ans = 0;
    for (int i = 0; i < N; i++) {
        if (d[i] <= A || (d[i] >= B && d[i] <= 2 * A)) ans++;
