    vector<bool> canSingle(N, false);
    for (int i = 0; i < N; i++) {
        int diff = abs(a[i] - b[i]);
        if (diff <= A || (B <= diff && diff <= 2 * A)) {
            canSingle[i] = true;
        }
    }

    // Precompute which pairs can be removed together
    vector<vector<bool>> canPair(N, vector<bool>(N, false));
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            int diff = abs((a[i] + b[i]) - (a[j] + b[j]));
            if (diff <= A || (B <= diff && diff <= 2 * A)) {
                canPair[i][j] = canPair[j][i] = true;
            }
        }
    }

    int totalMasks = 1 << N;
    vector<int> dp(totalMasks, -1);
    dp[0] = 0;

    for (int mask = 0; mask < totalMasks; mask++) {
        if (dp[mask] == -1) continue;
        for (int i = 0; i < N; i++) {
            if (mask & (1 << i)) continue;
            // Remove single i
            if (canSingle[i]) {
                int newMask = mask | (1 << i);
                dp[newMask] = max(dp[newMask], dp[mask] + 1);
            }
            // Remove pair (i, j)
            for (int j = i + 1; j < N; j++) {
                if (mask & (1 << j)) continue;
                if (canPair[i][j]) {
                    int newMask = mask | (1 << i) | (1 << j);
                    dp[newMask] = max(dp[newMask], dp[mask] + 1);
                }
            }
        }
    }

    cout << *max_element(dp.begin(), dp.end()) << "\n";
    return 0;
}

