/*
We have N pairs (a_i, b_i), and constants A, B.

For each element define:
  d_i = |a_i - b_i|
  s_i = a_i + b_i

One operation can remove:
1) one element i, if d_i is in [0, A] or in [B, 2A]
2) two different elements i, j, if |s_i - s_j| is in [0, A] or in [B, 2A]

We want the maximum number of operations.

Observation:
- A single removal gives 1 operation for one element.
- A pair removal also gives 1 operation for two elements.
So singles are always at least as good per element as pairs.
Thus:
  * Any element removable alone should always be removed alone.
  * Pairing is only useful among elements that are NOT removable alone.

So answer =
  (# of singly removable elements)
  + (maximum number of disjoint pairs among the remaining elements
     such that the pair condition holds on |s_i - s_j|)

Now among remaining elements, allowed pair differences are in:
  [0, A] union [B, 2A]
(assuming B <= 2A; otherwise second interval empty)

We need maximum matching in a graph on a line by values s_i, where edges depend only on distance.
For such "unit/proper interval style" condition, greedy by smallest available right endpoint works.

We process sorted s.
For each current smallest unused element x:
- If there exists an unused y > x with allowed difference, pairing x with the smallest such y is optimal.
- Otherwise x can never help later better than skipping it.

To support this efficiently, maintain unused indices in an ordered set.
For current smallest index i, try:
  candidate in [s_i, s_i + A]
  else candidate in [s_i + B, s_i + 2A]
excluding itself, smallest index > i satisfying range.

This greedy is standard exchange on sorted points.

Complexity: O(N log N)
*/

static inline bool single_ok(long long d, long long A, long long B) {
    if (d <= A) return true;
    if (B <= d && d <= 2 * A) return true;
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long A, B;
    cin >> N >> A >> B;

    long long singles = 0;
    vector<long long> remS;
    remS.reserve(N);

    for (int i = 0; i < N; ++i) {
        long long a, b;
        cin >> a >> b;
        long long d = llabs(a - b);
        long long s = a + b;
        if (single_ok(d, A, B)) singles++;
        else remS.push_back(s);
    }

    sort(remS.begin(), remS.end());
    int M = (int)remS.size();

    set<int> alive;
    for (int i = 0; i < M; ++i) alive.insert(i);

    long long pairs = 0;

    while (!alive.empty()) {
        int i = *alive.begin();
        long long x = remS[i];

        int chosen = -1;

        // First interval: [x, x + A], need index > i
        auto it = alive.upper_bound(i);
        if (it != alive.end() && remS[*it] <= x + A) {
            chosen = *it;
        } else {
            // Second interval: [x + B, x + 2A]
            if (B <= 2 * A) {
                auto it2 = alive.lower_bound(
                    (int)(lower_bound(remS.begin(), remS.end(), x + B) - remS.begin())
                );
                if (it2 != alive.end() && *it2 != i && remS[*it2] <= x + 2 * A) {
                    chosen = *it2;
                }
            }
        }

        if (chosen != -1) {
            pairs++;
            alive.erase(i);
            alive.erase(chosen);
        } else {
            alive.erase(i);
        }
    }

    cout << singles + pairs << '\n';
    return 0;
}

