import java.util.*;
import java.io.*;

public class Solution {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int A = Integer.parseInt(st.nextToken());
        int B = Integer.parseInt(st.nextToken());

        int[] d = new int[N]; // |a_i - b_i|
        int[] s = new int[N]; // a_i + b_i
        boolean[] used = new boolean[N];

        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            d[i] = Math.abs(a - b);
            s[i] = a + b;
        }

        int operations = 0;

        // First pass: remove single elements that qualify
        for (int i = 0; i < N; i++) {
            if (d[i] <= A || (B <= d[i] && d[i] <= 2 * A)) {
                used[i] = true;
                operations++;
            }
        }

        // Second pass: pair up remaining elements
        // Group remaining elements by their sum s
        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < N; i++) {
            if (!used[i]) {
                groups.computeIfAbsent(s[i], k -> new ArrayList<>()).add(i);
            }
        }

        // For each group, we can pair elements within the same sum (diff = 0 ≤ A always)
        for (List<Integer> list : groups.values()) {
            operations += list.size() / 2;
        }

        // Also try to pair elements with different sums
        // Get all remaining sums
        List<Integer> sums = new ArrayList<>(groups.keySet());
        Collections.sort(sums);

        // For each pair of sums, check if they can be paired
        for (int i = 0; i < sums.size(); i++) {
            List<Integer> listI = groups.get(sums.get(i));
            if (listI.size() % 2 == 0) continue; // Already fully paired

            // Need to find a partner for the leftover
            for (int j = i + 1; j < sums.size(); j++) {
                List<Integer> listJ = groups.get(sums.get(j));
                if (listJ.size() % 2 == 0) continue;

                int diff = Math.abs(sums.get(i) - sums.get(j));
                if (diff <= A || (B <= diff && diff <= 2 * A)) {
                    // Can pair the leftovers
                    operations++;
                    listI.remove(listI.size() - 1);
                    listJ.remove(listJ.size() - 1);
                    if (listI.isEmpty()) groups.remove(sums.get(i));
                    if (listJ.isEmpty()) groups.remove(sums.get(j));
                    break;
                }
            }
        }

        System.out.println(operations);
    }
}

